<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>                    <a href="{pigcms{:U('Shop/shop')}">{pigcms{$config['deliver_name']}店铺列表</a>|                    <a href="{pigcms{:U('Shop/open_shop')}">营业中店铺</a>                    <a href="{pigcms{:U('Shop/close_shop')}" class="on">未营业店铺</a>				</ul>			</div>            <table class="search_table" width="100%">                <tr>                    <td style="width:60%;">                        <form action="{pigcms{:U('Shop/close_shop')}" method="get">                            <input type="hidden" name="c" value="Shop"/>                            <input type="hidden" name="a" value="close_shop"/>                           &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;                            <if condition="$admin_area neq 3">                                <div id="choose_pca" province_idss="{pigcms{$_GET.province_idss}" city_idss="{pigcms{$_GET.city_idss}" area_id="{pigcms{$_GET.area_id}" circle_id="{pigcms{$_GET.circle_id}" style="display:inline"></div>                            </if>　　　&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;                            店铺名称:                            <input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>                            <input type="submit" value="查询" class="button"/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;                            <input type="button" id="export" value="导出" class="button"/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;                            <input type="text" value="" id="reason_val" style="display: none;"/>                            <input type="button" value="批量开店" id="online" class="button"/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;                            <input type="button" value="批量关店" id="offline" class="button"/>                        </form>                    </td>                </tr>            </table>            <div class="table-list">                <table width="100%" cellspacing="0">                    <thead>                        <tr>                            <th><input type="checkbox" id="all"></th>                            <th>编号</th>                            <th>店铺名称</th>                            <th>联系电话</th>                            <th>营业时间</th>                            <th>关店原因</th>                            <th>关店时间</th>                            <th>由谁关闭</th>                        </tr>                    </thead>                    <tbody>                        <if condition="count($order_list) gt 0">                            <volist name="order_list" id="vo">                                <tr>                                    <td><input type="checkbox" name="storeIds[]" value="{pigcms{$vo.store_id}"></td>                                    <td>{pigcms{$vo.store_id}</td>                                    <td>{pigcms{$vo.store_name}</td>                                    <td>{pigcms{$vo.store_phone}</td>                                    <td style="color:green;"><if condition="empty($vo['open_time_list'])">                                            数据未导入                                            <else/>                                            <select>                                                <volist name="vo.open_time_list" id="ti">                                                    <option disabled="disabled"<if condition="$ti.current eq 1">selected="selected"</if>>{pigcms{$ti.week_show}&nbsp;&nbsp;{pigcms{$ti.time_show}</option>                                                </volist>                                            </select>                                        </if></td>                                    <td<?php if($vo['is_close']==0){ ?> style="color: gray;" <?php } ?>>{pigcms{$vo.close_reason}</td>                                    <td><?php if($vo['close_time']!=0 && $vo['is_close']==1){ ?>                                            {pigcms{$vo.close_time|date="Y-m-d H:i:s",###}</td>                                        <?php }else{ ?>                                             -                                        <?php } ?>                                    <td><?php if($vo['close_by']==1){ ?>                                            <span style="color:red;font-weight: bold;">平台</span>                                        <?php }else if($vo['close_by']=='-'){ ?>                                            {pigcms{$vo.close_by}                                        <?php }else{ ?>                                            <span style="color: green;font-weight: bold;">商家</span>                                        <?php } ?></td>                                </tr>                            </volist>                            <tr><td class="textcenter pagebar" colspan="12">{pigcms{$pagebar}</td></tr>                        <else/>                            <tr><td class="textcenter red" colspan="12">暂无店铺！</td></tr>                        </if>                    </tbody>                </table>            </div>		</div><script src="{pigcms{$static_path}js/layer/layer.js"></script><script type="text/javascript">$(document).ready(function(){    layer.config({extend: 'extend/layer.ext.js'});    $('#all').click(function(){        if ($(this).is(':checked')) {            $('input[type="checkbox"]').attr('checked', true);        } else {            $('input[type="checkbox"]').attr('checked', false);        }    });    $('#export').click(function(){        var province = $('#choose_provincess').val();        var city = $('#choose_cityss').val();        var area = $('#choose_areass').val();        var circle = $('#choose_circle').val();        var keyword = $('input[name=keyword]').val();        var url = "{pigcms{:U('Shop/close_shop')}"        url += "&province_idss=" + province;        url += "&city_idss=" + city;        url += "&area_id=" + area;        url += "&circle_id=" + circle;        url += "&keyword=" + keyword;        url += "&export=1"        window.open(url);    });    $('#online').click(function(){        var storeIds = [];        $("input[name='storeIds[]']:checked").each(function(){            storeIds.push($(this).val());        });        if(storeIds.length < 1){            alert('请先选择店铺');            return false;        }        layer.confirm('确定开启店铺吗?', {icon: 3, title:'提示',offset: ['100px', '400px'],}, function(index){            $.post('{pigcms{:U("Shop/changeOnOffBusiness")}',{'type':0,'storeIds':storeIds},function(res){                if(res.errorno=='0'){                    alert(res.info);                }else{                    alert(res.info);                    window.location.reload();                }            },'json');            layer.close(index);        });    });    $('#offline').click(function(){        var storeIds = [];        $("input[name='storeIds[]']:checked").each(function(){            storeIds.push($(this).val());        });        if(storeIds.length < 1){            alert('请先选择店铺');            return false;        }        layer.prompt({            title: '请输入关店原因',            formType: 2,            value: $('#reason_val').val(),            offset: ['100px', '400px'],            yes: function (index, layero) {                var reason = layero.find(".layui-layer-input").val();                $('#reason_val').val(layero.find(".layui-layer-input").val());                $.post('{pigcms{:U("Shop/changeOnOffBusiness")}',{'type':1,'storeIds':storeIds,'reason':reason},function(res){                    if(res.errorno=='0'){                        alert(res.info);                    }else{                        alert(res.info);                        window.location.reload();                    }                },'json');                layer.close(index);            }        });    });});</script><script type="text/javascript" src="{pigcms{$static_path}js/area_pcac.js"></script><include file="Public:footer"/>